class Solution {
public:
    TreeNode* replaceValueInTree(TreeNode* root) {
        if (!root) return nullptr;
        root->val = 0;
        std::vector<TreeNode*> q = {root};
        while (!q.empty()) {
            int next_level_sum = 0;
            for (auto node : q) {
                if (node->left) next_level_sum += node->left->val;
                if (node->right) next_level_sum += node->right->val;
            }
            std::vector<TreeNode*> next_q;
            for (auto node : q) {
                int sibling_sum = 0;
                if (node->left) sibling_sum += node->left->val;
                if (node->right) sibling_sum += node->right->val;
                if (node->left) {
                    node->left->val = next_level_sum - sibling_sum;
                    next_q.push_back(node->left);
                }
                if (node->right) {
                    node->right->val = next_level_sum - sibling_sum;
                    next_q.push_back(node->right);
                }
            }
            q = std::move(next_q);
        }
        return root;
    }
};

class Solution {
    public TreeNode replaceValueInTree(TreeNode root) {
        if (root == null) return null;
        root.val = 0;
        List<TreeNode> q = new ArrayList<>();
        q.add(root);
        while (!q.isEmpty()) {
            int nextLevelSum = 0;
            for (TreeNode node : q) {
                if (node.left != null) nextLevelSum += node.left.val;
                if (node.right != null) nextLevelSum += node.right.val;
            }
            List<TreeNode> nextQ = new ArrayList<>();
            for (TreeNode node : q) {
                int siblingSum = 0;
                if (node.left != null) siblingSum += node.left.val;
                if (node.right != null) siblingSum += node.right.val;
                if (node.left != null) {
                    node.left.val = nextLevelSum - siblingSum;
                    nextQ.add(node.left);
                }
                if (node.right != null) {
                    node.right.val = nextLevelSum - siblingSum;
                    nextQ.add(node.right);
                }
            }
            q = nextQ;
        }
        return root;
    }
}

